import networkx as nx
G = nx.Graph()
for i in range(11):
    for j in range(i+1, 11):
        if len(list(G.neighbors(i))) < 3 and len(list(G.neighbors(j))) < 3:
            G.add_edge(i, j)
            if len(list(G.neighbors(i))) == 3:
                break
print([(u, v) for u, v in G.edges()])
